contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint a1, uint a2) public payable {
        require(a1 >= 1 ether && a2 > 0);
        require(address(this).balance >= a1 + a2);
        c.Deposit{value: a1 + a2}();
        bool ok1;
        try c.Collect(a2) { ok1 = true; } catch { ok1 = false; }
        uint midBal = c.balances(address(this));
        bool ok2;
        try c.Collect(a1) { ok2 = true; } catch { ok2 = false; }
        assert(ok1 && ok2 && c.balances(address(this)) == midBal - a1);
    }
    receive() external payable {}
}
